<?php
require_once __DIR__ . '/_layout.php'; requirePermission('inspections.manage');
$requiredPhotos=['front','rear','left','right','interior','dashboard'];
if(requestMethod()==='POST'){
    requireCsrfPost();$action=$_POST['action']??'';
    try{
        if($action==='create'){
            foreach($requiredPhotos as $photoType){if(!isset($_FILES['photos']['error'][$photoType])||$_FILES['photos']['error'][$photoType]!==UPLOAD_ERR_OK)throw new InvalidArgumentException(t('validation.inspection_photos'));}
            $id=withTransaction(function()use($requiredPhotos){$id=createInspection(['contract_id'=>(int)($_POST['contract_id']??0),'inspection_type'=>$_POST['inspection_type']??'','inspected_at'=>$_POST['inspected_at']??'','mileage'=>$_POST['mileage']??0,'fuel_level'=>$_POST['fuel_level']??0,'cleanliness'=>$_POST['cleanliness']??'','accessories'=>$_POST['accessories']??'','notes'=>$_POST['notes']??'','customer_signature_status'=>$_POST['customer_signature_status']??'pending']);foreach($requiredPhotos as $photoType){$file=['name'=>$_FILES['photos']['name'][$photoType],'type'=>$_FILES['photos']['type'][$photoType],'tmp_name'=>$_FILES['photos']['tmp_name'][$photoType],'error'=>$_FILES['photos']['error'][$photoType],'size'=>$_FILES['photos']['size'][$photoType]];$stored=storeValidatedImage($file,'inspections');dbExecute('INSERT INTO inspection_photos(inspection_id,photo_type,storage_path,mime_type,file_size,captured_at,created_by)VALUES(:inspection,:type,:path,:mime,:size,NOW(),:user)',['inspection'=>$id,'type'=>$photoType,'path'=>$stored['path'],'mime'=>$stored['mime_type'],'size'=>$stored['size'],'user'=>currentUserId()]);}return$id;});flash('success',t('message.inspection_validated',['id'=>$id]));
        }elseif($action==='damage'){
            $inspection=dbFetchOne('SELECT vi.*,r.agency_id FROM vehicle_inspections vi JOIN rental_contracts rc ON rc.id=vi.contract_id JOIN reservations r ON r.id=rc.reservation_id WHERE vi.id=:id',['id'=>(int)($_POST['inspection_id']??0)]);if(!$inspection)throw new InvalidArgumentException(t('validation.inspection_not_found'));requireAgencyAccess($inspection['agency_id']);$estimated=positiveMoney($_POST['estimated_cost']??'0')??'0.00';dbExecute('INSERT INTO vehicle_damages(inspection_id,vehicle_id,zone,damage_type,description,severity,estimated_cost,responsible_party,payment_status,status,created_by)VALUES(:inspection,:vehicle,:zone,:type,:description,:severity,:cost,:party,\'pending\',\'open\',:user)',['inspection'=>$inspection['id'],'vehicle'=>$inspection['vehicle_id'],'zone'=>trim((string)$_POST['zone']),'type'=>trim((string)$_POST['damage_type']),'description'=>trim((string)$_POST['description']),'severity'=>validateChoice($_POST['severity']??'',['minor','moderate','major'],'minor'),'cost'=>$estimated,'party'=>validateChoice($_POST['responsible_party']??'',['customer','agency','third_party','unknown'],'unknown'),'user'=>currentUserId()]);$id=(int)db()->lastInsertId();dbExecute("UPDATE vehicles SET status='damaged',updated_by=:user WHERE id=:vehicle",['user'=>currentUserId(),'vehicle'=>$inspection['vehicle_id']]);auditLog('damage.recorded','vehicle_damage',$id,null,['estimated_cost'=>$estimated],$inspection['agency_id']);flash('success',t('message.damage_recorded'));
        }
    }catch(InvalidArgumentException|DomainException $exception){flash('danger',$exception->getMessage());}catch(Throwable $exception){reportDatabaseError($exception,'Inspection operation failed');flash('danger',t('message.inspection_failed'));}safeRedirect('inspections.php');
}
$agencyIds=currentAgencyIds();if(!$agencyIds)$agencyIds=[0];$ph=implode(',',array_fill(0,count($agencyIds),'?'));$vehicleFilter=(int)($_GET['vehicle_id']??0);if($vehicleFilter&&!dbFetchOne("SELECT id FROM vehicles WHERE id=? AND agency_id IN ($ph) AND archived_at IS NULL",array_merge([$vehicleFilter],$agencyIds)))$vehicleFilter=0;$contractSql="SELECT rc.id,rc.contract_number,rc.status,r.reference,c.first_name,c.last_name,v.registration_number FROM rental_contracts rc JOIN reservations r ON r.id=rc.reservation_id JOIN customers c ON c.id=r.customer_id JOIN vehicles v ON v.id=r.vehicle_id WHERE r.agency_id IN ($ph) AND rc.status IN ('generated','signed','active','amended')";$contractParams=$agencyIds;$inspectionSql="SELECT vi.*,rc.contract_number,v.registration_number,c.first_name,c.last_name,(SELECT COUNT(*) FROM inspection_photos ip WHERE ip.inspection_id=vi.id) photo_count FROM vehicle_inspections vi JOIN rental_contracts rc ON rc.id=vi.contract_id JOIN reservations r ON r.id=rc.reservation_id JOIN vehicles v ON v.id=vi.vehicle_id JOIN customers c ON c.id=vi.customer_id WHERE r.agency_id IN ($ph)";$inspectionParams=$agencyIds;$comparisonSql="SELECT rc.contract_number,v.registration_number,co.mileage checkout_mileage,rt.mileage return_mileage,co.fuel_level checkout_fuel,rt.fuel_level return_fuel,TIMESTAMPDIFF(MINUTE,r.return_at,rt.inspected_at) late_minutes FROM rental_contracts rc JOIN reservations r ON r.id=rc.reservation_id JOIN vehicles v ON v.id=r.vehicle_id JOIN vehicle_inspections co ON co.contract_id=rc.id AND co.inspection_type='checkout' JOIN vehicle_inspections rt ON rt.contract_id=rc.id AND rt.inspection_type='return' WHERE r.agency_id IN ($ph)";$comparisonParams=$agencyIds;if($vehicleFilter){$contractSql.=' AND r.vehicle_id=?';$contractParams[]=$vehicleFilter;$inspectionSql.=' AND vi.vehicle_id=?';$inspectionParams[]=$vehicleFilter;$comparisonSql.=' AND r.vehicle_id=?';$comparisonParams[]=$vehicleFilter;}$contracts=dbFetchAll($contractSql.' ORDER BY rc.created_at DESC',$contractParams);$inspections=dbFetchAll($inspectionSql.' ORDER BY vi.inspected_at DESC LIMIT 100',$inspectionParams);$comparisons=dbFetchAll($comparisonSql.' ORDER BY rt.inspected_at DESC',$comparisonParams);
backofficeHeader('Inspections','inspections.php');?><?php pageHeader('Checkout and return inspections', 'Capture immutable vehicle condition, photos, mileage, fuel, and damage.', ['breadcrumbs'=>[['label'=>'Rentals'],['label'=>'Inspections']],'primary'=>['label'=>'Add inspection','href'=>'#new-inspection']]); ?><div class="grid"><section class="card" id="new-inspection"><h2><?=e(t('section.validate_inspection'))?></h2><form method="post" enctype="multipart/form-data"><?=csrfField()?><input type="hidden" name="action" value="create"><label><?=e(t('field.contract'))?><select name="contract_id"><?php foreach($contracts as $c):?><option value="<?=e($c['id'])?>"><?=e($c['contract_number'].' — '.$c['registration_number'].' — '.$c['first_name'].' '.$c['last_name'])?></option><?php endforeach;?></select></label><label><?=e(t('field.type'))?><select name="inspection_type"><option value="checkout"><?=e(t('option.checkout'))?></option><option value="return"><?=e(t('option.return'))?></option></select></label><label><?=e(t('field.date_time'))?><input type="datetime-local" name="inspected_at" value="<?=e(date('Y-m-d\TH:i'))?>" required></label><label><?=e(t('field.mileage'))?><input type="number" name="mileage" min="0" required></label><label><?=e(t('field.fuel_level'))?><input type="number" name="fuel_level" min="0" max="100" step="0.1" required></label><label><?=e(t('field.cleanliness'))?><select name="cleanliness"><?php foreach(['clean','acceptable','dirty'] as $cleanliness):?><option value="<?=e($cleanliness)?>"><?=e(t('option.'.$cleanliness))?></option><?php endforeach;?></select></label><label><?=e(t('field.accessories'))?><input name="accessories"></label><label><?=e(t('field.customer_signature'))?><select name="customer_signature_status"><option value="pending"><?=e(translatedStatus('pending'))?></option><option value="signed"><?=e(translatedStatus('signed'))?></option><option value="refused"><?=e(t('option.refused'))?></option></select></label><label><?=e(t('field.notes'))?><textarea name="notes"></textarea></label><div class="grid"><?php foreach($requiredPhotos as $photo):?><label><?=e(readableTranslationKey($photo).' — '.t('field.photos'))?><input type="file" name="photos[<?=e($photo)?>]" accept="image/jpeg,image/png,image/webp" required></label><?php endforeach;?></div><button class="btn primary"><?=e(t('action.validate_inspection'))?></button></form></section><section class="card"><h2><?=e(t('section.inspection_history'))?></h2><div class="table-wrap"><table><tr><th><?=e(t('field.contract'))?></th><th><?=e(t('field.vehicle'))?></th><th><?=e(t('field.type'))?></th><th><?=e(t('field.mileage'))?></th><th><?=e(t('field.fuel'))?></th><th><?=e(t('field.photos'))?></th><th><?=e(t('field.damage'))?></th></tr><?php foreach($inspections as $i):?><tr><td><bdi><?=e($i['contract_number'])?></bdi></td><td><bdi><?=e($i['registration_number'])?></bdi></td><td><?=statusBadge($i['inspection_type'])?></td><td><?=e($i['mileage'])?></td><td><?=e($i['fuel_level'])?>%</td><td><?=e($i['photo_count'])?>/6</td><td><form method="post"><?=csrfField()?><input type="hidden" name="action" value="damage"><input type="hidden" name="inspection_id" value="<?=e($i['id'])?>"><input name="zone" placeholder="<?=e(t('field.zone'))?>" required><input name="damage_type" placeholder="<?=e(t('field.damage_type'))?>" required><input name="description" placeholder="<?=e(t('field.description'))?>" required><select name="severity"><?php foreach(['minor','moderate','major'] as $severity):?><option value="<?=e($severity)?>"><?=e(t('option.'.$severity))?></option><?php endforeach;?></select><input name="estimated_cost" placeholder="<?=e(t('field.estimated_cost'))?>"><select name="responsible_party"><?php foreach(['customer','agency','third_party','unknown'] as $party):?><option value="<?=e($party)?>"><?=e(t('option.'.$party))?></option><?php endforeach;?></select><button class="btn danger"><?=e(t('action.record_damage'))?></button></form></td></tr><?php endforeach;?></table></div></section></div><section class="card" style="margin-top:1rem"><h2><?=e(t('section.inspection_comparison'))?></h2><div class="table-wrap"><table><tr><th><?=e(t('field.contract'))?></th><th><?=e(t('field.vehicle'))?></th><th><?=e(t('field.mileage_difference'))?></th><th><?=e(t('field.fuel_difference'))?></th><th><?=e(t('field.late_minutes'))?></th></tr><?php foreach($comparisons as $c):?><tr><td><?=e($c['contract_number'])?></td><td><?=e($c['registration_number'])?></td><td><?=e($c['return_mileage']-$c['checkout_mileage'])?> <?=e(t('unit.km'))?></td><td><?=e($c['return_fuel']-$c['checkout_fuel'])?>%</td><td><?=e(max(0,(int)$c['late_minutes']))?></td></tr><?php endforeach;?></table></div></section><?php backofficeFooter();
